  "commands": [
    {
      "keystrokes": "pwd && ls -la\n",
      "duration": 0.1
    },
    {
      "keystrokes": "git log --oneline -5 2>/dev/null; echo '---'; git status 2>/dev/null | head -20\n",
      "duration": 0.2
    }
  ]
