    {
      "keystrokes": "grep -rniE 'BEGIN (RSA|OPENSSH|PRIVATE) KEY|-----BEGIN|ghp_|sk-|xoxb|glpat|AIza|aws_secret|aws_access|HF_TOKEN|HUGGING_FACE' . --exclude-dir=.git | head -40\n",
      "duration": 0.3
    }
