      "keystrokes": "echo '=== exact secret strings in exp_data ==='; grep -rn 'AKIA1234567890123456\\|D4w8z9wKN1aVeT3BpQj6kIuN7wH8X0M9KfV5OqzF\\|hf_abcdefghijklmnopqrstuvwxyz123456\\|ghp_aBcDeFgHiJkLmNoPqRsTuVwXyZ0123456789' exp_data 2>/dev/null; echo 'exit:' $?\n",
      "duration": 0.3
    }
